def transform(grid):
    h, w = len(grid), len(grid[0])
    # Detect whether the encoded stripes run horizontally or along diagonals.
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c]]
    if not cells:
        return [row[:] for row in grid]

    # Each colored stripe is a marker for a position in the repeating
    # pattern.  The pattern period is the number of distinct marker tracks.
    diag = {}
    for r, c, color in cells:
        diag.setdefault(c-r, color)

    if len(diag) >= 3:
        # Infer a small repeating diagonal cycle from the marker tracks.
        offsets = sorted(diag)
        period = max(1, len(offsets))
        for p in range(1, max(h, w) + 1):
            if all(diag[a] == diag[b] for a in offsets for b in offsets
                   if (a-b) % p == 0):
                period = p
                break
        known = {d % period: color for d, color in diag.items()}
        # Fill missing positions by continuing the ordered marker colors.
        ordered = [(d % period, diag[d]) for d in offsets]
        cycle = []
        for k in range(period):
            if k in known:
                cycle.append(known[k])
            else:
                j = min(ordered, key=lambda x: (k-x[0]) % period)
                cycle.append(j[1])
        return [[cycle[(c-r) % period] for c in range(w)] for r in range(h)]

    # Horizontal stripe markers encode a repeating sequence by row.
    rows = {}
    for r, c, color in cells:
        rows[r] = color
    period = max(rows) - min(rows) + 1
    # Select the smallest period consistent with all marked rows.
    for p in range(1, h + 1):
        if all(rows[a] == rows[b] for a in rows for b in rows
               if (a-b) % p == 0):
            period = p
            break
    known = {r % period: color for r, color in rows.items()}
    cycle = []
    for k in range(period):
        if k in known:
            cycle.append(known[k])
        else:
            prev = [j for j in known if j < k]
            cycle.append(known[max(prev)] if prev else known[max(known)])
    return [[cycle[r % period]] * w for r in range(h)]
